import{_ as t,C as e,c as a,o as r,j as n,G as i,b as l,a0 as s,a as d,w as o,a1 as u}from"./chunks/framework.DKRgXLPU.js";const g=JSON.parse('{"title":"Bygga din rutin före fotografering","description":"","frontmatter":{},"headers":[],"relativePath":"sv/education/mental-strength/pre-shot-routine.md","filePath":"sv/education/mental-strength/pre-shot-routine.md"}');const k=t({name:"sv/education/mental-strength/pre-shot-routine.md"},[["render",function(t,g,k,h,p,m){const f=e("AdBanner"),v=e("Mermaid"),c=e("AdInArticle");return r(),a("div",null,[g[1]||(g[1]=n("h1",{id:"bygga-din-rutin-fore-fotografering",tabindex:"-1"},[d("Bygga din rutin före fotografering "),n("a",{class:"header-anchor",href:"#bygga-din-rutin-fore-fotografering","aria-label":'Permalink to "Bygga din rutin före fotografering"'},"​")],-1)),i(f),g[2]||(g[2]=n("p",null,"Din rutiner före skottet är ett av de kraftfullaste verktygen i ditt mentala spel. Det är en konsekvent sekvens av handlingar som förbereder dig för varje kast och utlöser ditt bästa prestationstillstånd.",-1)),g[3]||(g[3]=n("div",{class:"tip custom-block"},[n("p",{class:"custom-block-title"},"Den stora idén"),n("p",null,[n("strong",null,"Din rutin är din inkörsport till zonen."),d(' En konsekvent rutin före träning signalerar till din hjärna: "Det är dags att prestera." Med upprepning blir det en automatisk utlösare för topprestationer.')])],-1)),(r(),l(u,null,{default:o(()=>[i(v,{id:"mermaid-13",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BStarta%20rutinen%5D%20--%3E%20B%5BHj%C3%A4rnan%20k%C3%A4nner%20igen%20m%C3%B6nster%5D%0A%20%20%20%20B%20--%3E%20C%5BAutomatisk%20tillst%C3%A5ndsf%C3%B6rskjutning%5D%0A%20%20%20%20C%20--%3E%20D%5BExekveringsl%C3%A4ge%5D%0A%20%20%20%20D%20--%3E%20E%5BTopprestanda%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23e8f5e9%0A%20%20%20%20style%20D%20fill%3A%23fff4e1%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:o(()=>[...g[0]||(g[0]=[d(" Loading... ",-1)])]),_:1})),g[4]||(g[4]=s('<h2 id="varfor-rutiner-fungerar" tabindex="-1">Varför rutiner fungerar <a class="header-anchor" href="#varfor-rutiner-fungerar" aria-label="Permalink to &quot;Varför rutiner fungerar&quot;">​</a></h2><h3 id="konsekvens-skapar-fortroende" tabindex="-1">Konsekvens skapar förtroende <a class="header-anchor" href="#konsekvens-skapar-fortroende" aria-label="Permalink to &quot;Konsekvens skapar förtroende&quot;">​</a></h3><p>När du gör samma sak varje gång tar du bort variabler. Din kropp vet vad som kommer. Detta skapar en känsla av kontroll och förtrogenhet, även i okända situationer.</p><h3 id="rutiners-utlosande-tillstand" tabindex="-1">Rutiners utlösande tillstånd <a class="header-anchor" href="#rutiners-utlosande-tillstand" aria-label="Permalink to &quot;Rutiners utlösande tillstånd&quot;">​</a></h3><p>Med repetition kopplas din rutin till ditt prestationstillstånd. Att starta rutinen inleder automatiskt den mentala övergången till utförandeläge.</p><h3 id="rutiner-blockerar-distraktioner" tabindex="-1">Rutiner blockerar distraktioner <a class="header-anchor" href="#rutiner-blockerar-distraktioner" aria-label="Permalink to &quot;Rutiner blockerar distraktioner&quot;">​</a></h3><p>En rutin ger dig något att fokusera på. Det finns inget utrymme för oro för musiken, publiken eller vad som kan hända.</p><h3 id="rutiner-hanterar-upphetsning" tabindex="-1">Rutiner hanterar upphetsning <a class="header-anchor" href="#rutiner-hanterar-upphetsning" aria-label="Permalink to &quot;Rutiner hanterar upphetsning&quot;">​</a></h3><p>En väl utformad rutin hjälper till att reglera din energinivå – den lugnar dig om du är för upphetsad och fokuserar dig om du är trött.</p><h2 id="element-i-en-effektiv-rutin" tabindex="-1">Element i en effektiv rutin <a class="header-anchor" href="#element-i-en-effektiv-rutin" aria-label="Permalink to &quot;Element i en effektiv rutin&quot;">​</a></h2><h3 id="fas-1-bedomning-utanfor-cirkeln" tabindex="-1">Fas 1: Bedömning (utanför cirkeln) <a class="header-anchor" href="#fas-1-bedomning-utanfor-cirkeln" aria-label="Permalink to &quot;Fas 1: Bedömning (utanför cirkeln)&quot;">​</a></h3><p>Innan du går in, samla information:</p><ul><li>Läs terrängen (sluttningar, hinder, underlag)</li><li>Bedöm situationen (resultat, klotpositioner)</li><li>Välj ditt mål och landningsplats</li><li>Bestäm kasttyp (peka, skjut, lobb, rulla)</li></ul><p><strong>Det är här tänkandet sker.</strong> Ta din tid här.</p><h3 id="fas-2-overgang-att-komma-in-i-cirkeln" tabindex="-1">Fas 2: Övergång (Att komma in i cirkeln) <a class="header-anchor" href="#fas-2-overgang-att-komma-in-i-cirkeln" aria-label="Permalink to &quot;Fas 2: Övergång (Att komma in i cirkeln)&quot;">​</a></h3><p>Övergången från att tänka till att göra:</p><ul><li>Fysisk handling (gå in i cirkeln på ett konsekvent sätt)</li><li>Mental signal (ett ord eller en fras som signalerar &quot;utförandeläge&quot;)</li><li>Andning (ett medvetet andetag för att centrera dig)</li></ul><p><strong>Detta är strömbrytaren.</strong> Analysen slutar här.</p><h3 id="fas-3-uppstallning-i-cirkeln" tabindex="-1">Fas 3: Uppställning (i cirkeln) <a class="header-anchor" href="#fas-3-uppstallning-i-cirkeln" aria-label="Permalink to &quot;Fas 3: Uppställning (i cirkeln)&quot;">​</a></h3><p>Förbered din kropp:</p><ul><li>Konsekvent hållning (samma varje gång)</li><li>Greppkontroll (känn på klotet)</li><li>Anpassning till målet</li><li>Fysisk trigger (en liten rörelse som är din)</li></ul><h3 id="fas-4-visualisering-kortfattad" tabindex="-1">Fas 4: Visualisering (kortfattad) <a class="header-anchor" href="#fas-4-visualisering-kortfattad" aria-label="Permalink to &quot;Fas 4: Visualisering (kortfattad)&quot;">​</a></h3><p>Se kastet innan du gör det:</p><ul><li>Föreställ dig bollens bana (max 2–3 sekunder)</li><li>Känn det lyckade kastet</li><li>Få visuell kontakt med din målgrupp</li></ul><h3 id="fas-5-utforande" tabindex="-1">Fas 5: Utförande <a class="header-anchor" href="#fas-5-utforande" aria-label="Permalink to &quot;Fas 5: Utförande&quot;">​</a></h3><p>Gör kastet:</p><ul><li>Externt fokus (endast mål)</li><li>Lita på din kropp</li><li>Släpp utan tvekan</li><li>Följ upp naturligt</li></ul>',27)),i(c),g[5]||(g[5]=s('<h2 id="bygga-din-personliga-rutin" tabindex="-1">Bygga din personliga rutin <a class="header-anchor" href="#bygga-din-personliga-rutin" aria-label="Permalink to &quot;Bygga din personliga rutin&quot;">​</a></h2><h3 id="steg-1-observera-vad-du-redan-gor" tabindex="-1">Steg 1: Observera vad du redan gör <a class="header-anchor" href="#steg-1-observera-vad-du-redan-gor" aria-label="Permalink to &quot;Steg 1: Observera vad du redan gör&quot;">​</a></h3><p>Du har förmodligen redan en viss rutin. Observera:</p><ul><li>Vad gör man innan man gör bra kast?</li><li>Vad känns naturligt för dig?</li><li>Vad hjälper dig att fokusera?</li></ul><h3 id="steg-2-utforma-din-rutin" tabindex="-1">Steg 2: Utforma din rutin <a class="header-anchor" href="#steg-2-utforma-din-rutin" aria-label="Permalink to &quot;Steg 2: Utforma din rutin&quot;">​</a></h3><p>Skapa en sekvens som inkluderar:</p><ul><li>[ ] Bedömningsfas</li><li>[ ] Tydligt övergångsmoment</li><li>[ ] Konsekvent fysisk uppställning</li><li>[ ] Kort visualisering</li><li>[ ] Exekveringsutlösare</li></ul><h3 id="steg-3-skriv-ner-det" tabindex="-1">Steg 3: Skriv ner det <a class="header-anchor" href="#steg-3-skriv-ner-det" aria-label="Permalink to &quot;Steg 3: Skriv ner det&quot;">​</a></h3><p>Var specifik. Exempel:</p><ol><li><strong>Bedöm:</strong> Läs terrängen, välj landningsplats</li><li><strong>Övergång:</strong> Gå in i cirkeln med vänster fot först, säg &quot;lita på&quot;</li><li><strong>Uppställning:</strong> Fötterna axelbrett, greppkontroll, rikta axlarna</li><li><strong>Visualisera:</strong> Se vägen, känn befrielsen</li><li><strong>Utför:</strong> Blicken riktad mot målet, kast</li></ol><h3 id="steg-4-utova-religiost" tabindex="-1">Steg 4: Utöva religiöst <a class="header-anchor" href="#steg-4-utova-religiost" aria-label="Permalink to &quot;Steg 4: Utöva religiöst&quot;">​</a></h3><p>Använd din rutin på VARJE kast under träningen:</p><ul><li>Enkla kast</li><li>Svåra kast</li><li>När du är trött</li><li>När du är fräsch</li></ul><p>Rutinen måste bli automatisk.</p><h3 id="steg-5-forfina-over-tid" tabindex="-1">Steg 5: Förfina över tid <a class="header-anchor" href="#steg-5-forfina-over-tid" aria-label="Permalink to &quot;Steg 5: Förfina över tid&quot;">​</a></h3><p>Din rutin kommer att utvecklas. Lägg märke till vad som fungerar och justera. Men ändra den inte under tävling – bara mellan evenemang.</p><h2 id="rutinmassig-tidtagning" tabindex="-1">Rutinmässig tidtagning <a class="header-anchor" href="#rutinmassig-tidtagning" aria-label="Permalink to &quot;Rutinmässig tidtagning&quot;">​</a></h2><p>Din rutin bör ta en jämn tid:</p><ul><li>För fort: Du har bråttom, inte ordentligt förberedd</li><li>För långsamt: Du övertänker och tappar flödet</li><li>Precis lagom: Tillräckligt med tid att förbereda sig, inte så mycket att du tänker för mycket</li></ul><p><strong>Typisk tidpunkt:</strong></p><ul><li>Bedömning: 5–10 sekunder</li><li>Övergång + Uppställning: 3–5 sekunder</li><li>Visualisering + Utförande: 3–5 sekunder</li><li><strong>Totalt: 10–20 sekunder</strong></li></ul><h2 id="vanliga-rutinmassiga-misstag" tabindex="-1">Vanliga rutinmässiga misstag <a class="header-anchor" href="#vanliga-rutinmassiga-misstag" aria-label="Permalink to &quot;Vanliga rutinmässiga misstag&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Misstag</th><th>Problem</th><th>Lösning</th></tr></thead><tbody><tr><td>Hoppning i praktiken</td><td>Rutin är inte automatisk</td><td>Använd den varje kast</td></tr><tr><td>För komplicerat</td><td>Svårt att komma ihåg under press</td><td>Förenkla till det väsentliga</td></tr><tr><td>Tänkande under utförandet</td><td>Stör automatisk prestanda</td><td>Tydlig övergångspunkt</td></tr><tr><td>Inkonsekvent timing</td><td>Skapar osäkerhet</td><td>Öva med jämn takt</td></tr><tr><td>Förändring mitt i tävlingen</td><td>Introducerar tvivel</td><td>Håll dig till det du vet</td></tr></tbody></table><h2 id="rutinmassig-felsokning" tabindex="-1">Rutinmässig felsökning <a class="header-anchor" href="#rutinmassig-felsokning" aria-label="Permalink to &quot;Rutinmässig felsökning&quot;">​</a></h2><p><strong>Om du har bråttom:</strong></p><ul><li>Lägg till ett andetag vid övergången</li><li>Sakta ner dina uppställningsrörelser</li><li>Pausa före visualisering</li></ul><p><strong>Om du övertänker:</strong></p><ul><li>Förkorta rutinen</li><li>Använd en starkare övergångssignal</li><li>Fokusera mer externt</li></ul><p><strong>Om du är inkonsekvent:</strong></p><ul><li>Filma dig själv för att kontrollera</li><li>Öva rutinen utan att kasta</li><li>Få feedback från en partner</li></ul><h2 id="exempelrutiner" tabindex="-1">Exempelrutiner <a class="header-anchor" href="#exempelrutiner" aria-label="Permalink to &quot;Exempelrutiner&quot;">​</a></h2><h3 id="enkel-rutin" tabindex="-1">Enkel rutin <a class="header-anchor" href="#enkel-rutin" aria-label="Permalink to &quot;Enkel rutin&quot;">​</a></h3><ol><li>Välj mål</li><li>Kliv in, andas</li><li>Greppa, rikta in</li><li>Se det, kasta det</li></ol><h3 id="detaljerad-rutin" tabindex="-1">Detaljerad rutin <a class="header-anchor" href="#detaljerad-rutin" aria-label="Permalink to &quot;Detaljerad rutin&quot;">​</a></h3><ol><li>Läs terrängen, välj landningsplats</li><li>Steg först med vänster fot</li><li>Säg &quot;smidig&quot; internt</li><li>Ett andetag, axlarna sänks</li><li>Fötterna satta, greppkontroll</li><li>Rikta in axlarna mot målet</li><li>Se vägen (2 sekunder)</li><li>Ögonen låses på målet</li><li>Kasta</li></ol><h2 id="viktig-slutsats" tabindex="-1">Viktig slutsats <a class="header-anchor" href="#viktig-slutsats" aria-label="Permalink to &quot;Viktig slutsats&quot;">​</a></h2><blockquote><p>Din rutin är ditt ankare. I kaos är den din konstant.</p></blockquote><p>Bygg det noggrant. Öva alltid. Lita helt och hållet på det.</p>',38)),i(f)])}]]);export{g as __pageData,k as default};
